    "q": "Pathogenic E. coli กลุ่ม EHEC, VTEC หรือ STEC เช่น E. coli O157:H7 ซึ่งพบในเนื้อวัวบดและนมดิบ มีลักษณะใด",
    "options": [
      "สร้าง enterotoxin ในลำไส้หลังกินเชื้อจำนวนมาก ทำให้เกิด pseudo-appendicitis และไข้นาน 1 ถึง 3 สัปดาห์",
      "สร้าง Shiga-like toxin ทำให้เกิด hemorrhagic colitis และ HUS ซึ่งมี hemolytic anemia, thrombocytopenia และไตวายเฉียบพลัน",
      "สร้าง Shiga-like toxin ทำให้เกิด hemorrhagic colitis และ HUS ซึ่งมี hemolytic anemia, leukocytosis และภาวะตับวายเฉียบพลัน",
      "ไม่เพิ่มจำนวนในเนื้อ แต่เจริญดีที่ 42 องศาเซลเซียส ทำให้ท้องเสีย และเป็นโรคที่หายได้เอง"
    ],
    "answer": 1,
    "explain": "Pathogenic E. coli ที่เกี่ยวข้องกับเนื้อคือกลุ่ม EHEC, VTEC หรือ STEC ซึ่งสร้าง Shiga-like toxin ทำให้เกิด hemorrhagic colitis (ปวดท้องเกร็ง ถ่ายเป็นน้ำ และถ่ายเป็นเลือด) และ hemolytic uremic syndrome (HUS) ซึ่งองค์ประกอบคือ hemolytic anemia, thrombocytopenia และไตวายเฉียบพลัน ไม่ใช่ leukocytosis กับตับวาย ตัวที่รู้จักดีคือ E. coli O157:H7 ซึ่งพบในเนื้อวัวบดและนมดิบ ป้องกันด้วยการปรุงอาหารให้สุกทั่วถึงและหลีกเลี่ยงการปนเปื้อนข้าม ส่วน enterotoxin ที่สร้างในลำไส้หลังกินเชื้อจำนวนมากเป็นของ Clostridium perfringens และ pseudo-appendicitis เป็นอาการจาก Yersinia enterocolitica",
