    "explain": "ในสัตว์ทุกชนิดที่สงสัยว่าเป็นโรคแบบ systemic หรือ generalized ที่ให้ผลบวกต่อการทดสอบวินิจฉัยวัณโรค หรือที่พบรอยโรคชวนสงสัยวัณโรคในการตรวจซาก ต้องกรีดตรวจต่อมน้ำเหลืองหลักของซาก ได้แก่ precrural, popliteal, anal, superficial inguinal, ischiatic, internal และ external iliac, lumbar, renal, sternal, prepectoral, prescapular และ atlantal รวมทั้งต่อมน้ำเหลืองที่หัวและเครื่องใน ในซากทั่วไปต่อมน้ำเหลืองของซากตรวจด้วยการดูและคลำ และการกรีด supramammary เมื่อเต้านมให้นมหรืออักเสบเป็นข้อกำหนดของต่อมนั้นต่อมเดียว",
