    "explain": "septicemia คือภาวะที่มีแบคทีเรียก่อโรคและ toxin ในเลือด การวินิจฉัยที่แน่นอนต้องแยกเชื้อจากกระแสเลือด ซึ่งไม่ได้ทำในการตรวจก่อนฆ่าตามปกติ จึงตัดสินจากสิ่งที่พบในการตรวจก่อนและหลังฆ่า เช่น ซึม หายใจลำบากและเร็ว สั่น อุณหภูมิร่างกายเปลี่ยน ม้ามโต ต่อมน้ำเหลืองโตบวมน้ำหรือมีเลือดออก และจุดเลือดออกที่ไต ผิวหัวใจ เยื่อเมือก และเยื่อเซรุ่ม สัตว์ ซาก และชิ้นส่วนที่แยกออกจากสัตว์ที่เป็น septicemia ต้องทำลาย และในรายก้ำกึ่งให้ตรวจทางแบคทีเรียเมื่อทำได้ การกักซาก 48 ชั่วโมงเป็นวิธีจัดการกลิ่นเพศ ไม่ใช่ septicemia",
