    "explain": "Campylobacter jejuni เป็นแกรมลบที่เป็น microaerophilic ไม่เพิ่มจำนวนในเนื้อและอาหาร แต่เจริญดีที่ 42 องศาเซลเซียส (thermophilic Campylobacter) แหล่งที่ทำให้คนป่วยคือเนื้อสัตว์ปีกดิบหรือปรุงไม่สุก นมดิบ และน้ำดื่มที่ไม่ได้บำบัด อาการทางเดินอาหารคล้ายโรคจากเชื้อก่อโรคทางอาหารชนิดอื่น เป็นโรคที่หายได้เอง และควบคุมป้องกันแบบเดียวกับ Salmonella เชื้อที่เจริญได้ที่อุณหภูมิต่ำและสัมพันธ์กับสุกรคือ Yersinia enterocolitica ส่วนเชื้อสร้างสปอร์ที่ก่อโรคเมื่อเนื้อสุกวางไว้ที่อุณหภูมิห้องนานเกิน 2 ชั่วโมงคือ Clostridium perfringens",
