    "q": "เชื้อก่อโรคในเนื้อชนิดใดเป็นแกรมลบ facultative anaerobe ที่เจริญได้ที่อุณหภูมิต่ำ สัมพันธ์กับสุกรเป็นหลัก และทำให้ไข้ ปวดท้อง ถ่ายเป็นเลือดนาน 1 ถึง 3 สัปดาห์ ร่วมกับอาการคล้ายไส้ติ่งอักเสบ",
