    "year": 5,
    "type": "mcq",
    "q": "ชุดใดที่ทุกวิธีในชุดอยู่ในขั้นทำลายหรือลดจำนวนจุลินทรีย์ที่ปนเปื้อนเนื้อ",
    "options": [
      "ล้างซากด้วยน้ำร้อน พ่นสารละลายกรดแลคติก 1–2% และ steam pasteurization",
      "ล้างซากด้วยน้ำร้อน บรรจุสุญญากาศ และเติมคาร์บอนไดออกไซด์ในบรรจุภัณฑ์",
      "ไม่เปิดช่องท้องก่อนถลกหนัง ป้องกันซากสัมผัสกัน และทำความสะอาดอุปกรณ์",
      "ลดอุณหภูมิซากลงถึง 4 องศาเซลเซียสในเวลาสั้น พ่นกรดแลคติก 1–2% และบรรจุสุญญากาศ"
    ],
    "answer": 0,
    "explain": "ขั้นทำลายหรือลดจำนวนจุลินทรีย์ที่ปนเปื้อนเนื้อ ได้แก่ การตัดแต่ง การล้างซากด้วยน้ำร้อน (82 องศาเซลเซียส) การพ่นซากด้วยสารละลายกรดอินทรีย์ เช่น กรดแลคติก 1–2% steam pasteurization และการฉายรังสี เช่น รังสีแกมมา 5 kGy ส่วนการลดอุณหภูมิเนื้อและซากลงถึง 4 องศาเซลเซียสในเวลาสั้น การบรรจุสุญญากาศ และการเติมคาร์บอนไดออกไซด์หรือไนตรัสออกไซด์ในบรรจุภัณฑ์ อยู่ในขั้นป้องกันหรือชะลอการเจริญและการเพิ่มจำนวนของจุลินทรีย์ และการไม่เปิดช่องท้องก่อนถลกหนังอยู่ในขั้นป้องกันการปนเปื้อน",
    "source": "Microbiology of meat หน้า 56-58",
