    "q": "การเปลี่ยนแปลงหลังตายของปลาแบ่งเป็นระยะ pre-rigor, rigor mortis และ post-rigor ข้อใดถูกต้อง",
    "options": [
      "ปลายังสดเฉพาะระยะ pre-rigor เพราะกิจกรรมของแบคทีเรียเพิ่มขึ้นตั้งแต่เริ่มเข้าระยะ rigor mortis",
      "ปลายังสดในระยะ pre-rigor และ rigor mortis ส่วนกิจกรรมของแบคทีเรียเพิ่มขึ้นในระยะ post-rigor",
      "ปลาสดที่สุดในระยะ post-rigor เพราะเอนไซม์ย่อย actomyosin จนกล้ามเนื้อกลับมานุ่ม",
      "กิจกรรมของแบคทีเรียสูงสุดในระยะ pre-rigor แล้วลดลงเมื่อ ATP ในกล้ามเนื้อหมด"
    ],
    "answer": 1,
    "explain": "ในระยะ pre-rigor กล้ามเนื้อยังมี ATP ซึ่ง myosin จับอยู่ เมื่อ ATP หมดจะเกิด actomyosin และปลาเข้าระยะ rigor mortis ซึ่งยังนับว่าสด ใน Quality Index Method ปลาที่แข็งอยู่ในระยะ rigor mortis ได้คะแนนความแข็ง 0 ซึ่งเป็นคะแนนที่ดีที่สุด ในระยะ post-rigor เอนไซม์ที่ย่อยตัวเอง (autolytic enzymes) ปลดปล่อย actomyosin เนื้อกลับนิ่ม pH สูงขึ้น และกิจกรรมของแบคทีเรียเพิ่มขึ้น เนื้อที่กลับมานิ่มในระยะนี้จึงเป็นสัญญาณของการเสื่อม ไม่ใช่ความสด",
