    "q": "จงจัดกลุ่ม chlorhexidine, iodine, aldehydes, phenolic compounds, sodium hypochlorite, alcohol, halogen compounds และ quaternary ammonium compounds (QACs) ว่าเป็น antiseptic, disinfectant หรือใช้ได้ทั้งสองแบบ และบอกว่าสารฆ่าเชื้อใดออกฤทธิ์ดีในสภาวะกรด (pH ต่ำ) และสารใดออกฤทธิ์ดีในสภาวะเบส",
