    "type": "mcq",
    "q": "ข้อใดเป็นลักษณะและการใช้งานของ sodium hypochlorite",
    "options": [
      "สารที่ใช้ล้างมดลูกที่ติดเชื้อและทาผิวหนังก่อนผ่าตัด เพราะระคายเคืองน้อย",
      "น้ำยาฟอกขาวในบ้าน ใช้กับผ้าเปื้อนเลือดหรือซีรัม และทำความสะอาดพื้นผิว",
      "สารที่ใช้ทำความสะอาดผิวหนังและแช่อุปกรณ์การแพทย์ ผสม formalin แล้วฆ่าสปอร์ได้",
      "สารที่ใช้ขจัดตะกรันนมในอุปกรณ์ CIP และอุปกรณ์ให้ความร้อน"
    ],
    "answer": 1,
    "explain": "Sodium hypochlorite คือน้ำยาฟอกขาว (liquid bleach) ที่ใช้ทำความสะอาดในบ้าน ออกฤทธิ์ผ่าน hypochlorous acid (HOCl) และใช้เป็น disinfectant กับผ้าที่เปื้อนเลือดหรือซีรัม และใช้ทำความสะอาดพื้นผิว ส่วนการล้างมดลูกที่ติดเชื้อและทาก่อนผ่าตัดเป็นการใช้ iodophores การแช่อุปกรณ์การแพทย์และการผสม formalin เพื่อฆ่าสปอร์เป็นการใช้แอลกอฮอล์ และการขจัดตะกรันนมในอุปกรณ์ CIP เป็นงานของกรดไนตริก",
