    "explain": "Formaldehyde (formalin) เป็น aldehyde ที่ International Agency for Research on Cancer (IARC) จัดเป็นสารก่อมะเร็งในมนุษย์กลุ่มที่ 1 และใช้ผสมกับ isopropyl alcohol เพื่อให้ออกฤทธิ์เร็วขึ้น aldehydes ระคายเคืองตาและมีกลิ่นแรง จึงไม่ใช่สารทาผิวหนัง และออกฤทธิ์ด้วย alkylation กับหมู่ amine ของโปรตีน ไม่ใช่การออกซิไดซ์หมู่ไทออลซึ่งเป็นกลไกของ halogens",
