    "explain": "Glutaraldehyde (ความเข้มข้นมากกว่า 2%) ใช้กับอุปกรณ์ที่ไม่ทนความร้อน ระเหยและระคายเคืองน้อยกว่า formaldehyde และยังฆ่าสปอร์ได้ดีกว่าด้วย สภาวะที่ glutaraldehyde ออกฤทธิ์ดีคือเบส จึงไม่ใช่สารขจัดตะกรันนมซึ่งเป็นงานของกรด การทาผิวหนังก่อนผ่าตัดเป็นการใช้ antiseptic อย่าง chlorhexidine และการฆ่าเชื้อน้ำประปาและสระว่ายน้ำเป็นการใช้คลอรีน",
