    "answer": 2,
    "explain": "Chlorhexidine เป็น antiseptic ที่ออกฤทธิ์เร็วและระคายเคืองน้อย ฆ่าแบคทีเรียแกรมบวกได้ดีกว่าแกรมลบ รวมทั้งไวรัสและเชื้อราบางชนิด จุดเด่นคือยังออกฤทธิ์ได้ดีเมื่อมีสารอินทรีย์ ตรงข้ามกับ iodophores ที่ฤทธิ์ลดลงเมื่อมีสารอินทรีย์ chlorhexidine ทำงานดีในสภาวะเบส ออกฤทธิ์โดยดูดซับบนผิวเซลล์ ทำลายเยื่อหุ้มเซลล์ และทำให้โปรตีนตกตะกอน ใช้จุ่มหัวนม ทำความสะอาด และขัดผิวก่อนผ่าตัด",
