    "explain": "สารออกฤทธิ์หลักของคลอรีนคือ hypochlorous acid (HOCl) ซึ่งเกิดเมื่อคลอรีนละลายน้ำ (Cl₂ + H₂O → HOCl + H⁺ + Cl⁻) และได้ผลดีเมื่อ pH ต่ำกว่า 7.5 คลอรีนใช้กับน้ำประปา สระว่ายน้ำ และทำความสะอาดหัวนม ฆ่าแบคทีเรีย โปรโตซัว และไวรัสได้ แต่ประสิทธิภาพลดลงเมื่อมีสารอินทรีย์ OCl⁻ เป็นรูปที่ HOCl แตกตัวออกมา ส่วนการแช่อุปกรณ์ที่ไม่ทนความร้อนเป็นการใช้ glutaraldehyde การล้างแผลเป็นการใช้ hydrogen peroxide และการล้างมดลูกที่ติดเชื้อเป็นการใช้ iodophores",
