    "year": 5,
    "type": "mcq",
    "q": "ข้อใดถูกต้องเกี่ยวกับวิธีทางจุลชีววิทยาในการประเมินคุณภาพปลา",
    "options": [
      "Total counts ระบุชนิดแบคทีเรียที่เป็นสาเหตุหลักของการเน่าเสียได้โดยตรง",
      "Detection of spoilage bacteria นับแบคทีเรียทั้งหมดรวมทั้งชนิดที่ไม่ทำให้เน่าเสียโดยไม่แยกชนิด",
      "Total counts นับแบคทีเรียที่เจริญเป็นโคโลนีที่มองเห็นได้ และบ่งชี้อายุการเก็บรักษาได้ดี",
      "วิธีทางจุลชีววิทยาทำได้เร็วและไม่ทำลายตัวอย่าง จึงใช้กับสัตว์น้ำได้ทุกชนิด"
    ],
    "answer": 2,
    "explain": "Total counts คือจำนวนแบคทีเรียทั้งหมดที่เจริญเป็นโคโลนีที่มองเห็นได้ และเป็นตัวบ่งชี้อายุการเก็บรักษา (shelf life) ของผลิตภัณฑ์ที่ดี ส่วน detection of spoilage bacteria ใช้ตรวจหาแบคทีเรียบางชนิดที่เป็นสาเหตุหลักของการเน่าเสีย การทำได้เร็ว ไม่ทำลายตัวอย่าง และใช้ได้กับสัตว์น้ำทุกชนิดเป็นข้อดีของวิธีทางประสาทสัมผัส ไม่ใช่วิธีทางจุลชีววิทยา",
    "source": "MI_SP_E1.2 หน้า 38 และ 44",
