    "q": "ข้อใดถูกต้องเกี่ยวกับการวัดคุณสมบัติทางไฟฟ้า (electrical properties) ของปลาเพื่อประเมินความสด",
    "options": [
      "วัดปริมาณ TMA, DMA และแอมโมเนียในเนื้อปลาโดยตรง จึงเหมาะกับการตรวจหมึกและกุ้ง",
      "วัดการเปลี่ยนแปลงหลังตายหรือระดับการเน่าเสีย แต่ค่าเปลี่ยนเมื่อปลาแช่แข็ง เสียหาย หรือเอาเลือดออก",
      "ให้ค่าคงที่ไม่ว่าปลาจะผ่านการแช่แข็ง เสียหาย หรือเอาเลือดออกมาก่อน จึงเชื่อถือได้สูงกว่าวิธีอื่น",
      "เป็นวิธีทางประสาทสัมผัสที่ใช้ตา จมูก และการสัมผัสของผู้ประเมินให้คะแนนความสด"
    ],
    "answer": 1,
    "explain": "การวัดคุณสมบัติทางไฟฟ้าเป็นวิธีทางกายภาพที่ใช้วัดการเปลี่ยนแปลงหลังตายหรือระดับการเน่าเสียของปลา ข้อจำกัดคือค่าที่อ่านได้จะต่างไปเมื่อปลาผ่านการแช่แข็ง เสียหาย หรือถูกเอาเลือดออก ส่วนการวัด TMA, DMA และแอมโมเนียคือการวัด TVB-N ซึ่งเป็นวิธีทางชีวเคมีและเคมี และการให้คะแนนจากลักษณะภายนอก กลิ่น และเนื้อสัมผัสเป็นวิธีทางประสาทสัมผัส",
