    "year": 5,
    "type": "mcq",
    "q": "สารพิษในอาหารทะเลชนิดใดทำให้เกิดอาการทางทางเดินอาหาร และมีคุณสมบัติก่อการกลายพันธุ์และก่อมะเร็ง",
    "options": [
      "Okadaic acid",
      "Domoic acid",
      "Tetrodotoxin",
      "Azaspiracids"
    ],
    "answer": 0,
    "explain": "Okadaic acid สร้างโดย dinoflagellate กลุ่ม Dinophysis และทำให้เกิด diarrhetic shellfish poisoning (DSP) มีอาการทางทางเดินอาหาร ได้แก่ ท้องเสีย ปวดท้อง คลื่นไส้ อาเจียน และหนาวสั่น หายเป็นปกติใน 3 วัน และมีคุณสมบัติก่อการกลายพันธุ์และก่อมะเร็ง พบมากในญี่ปุ่นและยุโรปตอนเหนือจากการกินหอยแมลงภู่ หอยเชลล์ และหอยกาบที่มีพิษ azaspiracids ก็ทำให้เกิดอาการทางทางเดินอาหารเช่นกัน แต่คุณสมบัติก่อการกลายพันธุ์และก่อมะเร็งเป็นจุดเด่นของ okadaic acid ส่วน domoic acid ทำให้สูญเสียความจำและชัก และ tetrodotoxin จากปลาปักเป้าออกฤทธิ์ต่อระบบประสาทคล้าย PSP",
