    "type": "mcq",
    "q": "ข้อใดถูกต้องเกี่ยวกับ azaspiracid shellfish poisoning (AZP)",
    "options": [
      "เกิดจาก azaspiracids พบมากในหอยแมลงภู่ และทำให้เกิดอาการทางทางเดินอาหาร",
      "เกิดจาก azaspiracids พบมากในปลาเขตร้อน และทำให้รับรู้ร้อนเย็นสลับกัน",
      "เกิดจาก azaspiracids ที่ไดอะตอมสร้าง และทำให้สูญเสียความจำและชัก",
      "เกิดจาก azaspiracids พบมากในปลาปักเป้า และทำให้เกิดอัมพาตแบบลุกลามขึ้นจนเสียชีวิต"
    ],
    "answer": 0,
    "explain": "AZP เกิดจากการกินหอยที่ปนเปื้อน azaspiracids ซึ่งสร้างโดย dinoflagellate (Azadinium และ Protoperidinium) พบมากในหอยแมลงภู่ รวมทั้งหอยนางรม หอยกาบ และหอยเชลล์ ทำให้เกิดอาการทางทางเดินอาหาร ได้แก่ ท้องเสีย ปวดท้อง คลื่นไส้ และอาเจียน พบในหอยแมลงภู่จากยุโรป แอฟริกาเหนือ และญี่ปุ่น ส่วนการรับรู้ร้อนเย็นสลับกันเป็นอาการของ ciguatera การสูญเสียความจำและชักเป็นอาการของ domoic acid ซึ่งไดอะตอมสร้าง และอัมพาตแบบลุกลามขึ้นเป็นอาการของ saxitoxin",
