    "year": 5,
    "type": "mcq",
    "q": "สารพิษใดส่งผลต่อทั้งระบบประสาทส่วนกลางและส่วนปลาย ทำให้เดินเซ กล้ามเนื้อทำงานไม่ประสานกัน และเกิดอัมพาตแบบลุกลามขึ้น (ascending paralysis)",
    "options": [
      "Brevetoxin",
      "Saxitoxin",
      "Ciguatoxin",
      "Domoic acid"
    ],
    "answer": 1,
    "explain": "Saxitoxin สร้างโดย dinoflagellate และทำให้เกิด paralytic shellfish poisoning (PSP) ส่งผลต่อทั้งระบบประสาทส่วนกลางและส่วนปลาย เริ่มจากรู้สึกเหมือนเข็มทิ่มที่ริมฝีปาก ลิ้น และปลายนิ้ว ตามด้วยเดินเซ กล้ามเนื้อทำงานไม่ประสานกัน และอัมพาตแบบลุกลามขึ้น อาจเสียชีวิตจากระบบหายใจล้มเหลว brevetoxin และ ciguatoxin ทำให้เกิดทั้งอาการทางเดินอาหารและอาการทางประสาท โดย ciguatoxin ทำให้รับรู้ร้อนเย็นสลับกันและชาที่ริมฝีปาก ลิ้น และนิ้ว ส่วน domoic acid ทำให้สูญเสียความจำและชัก",
