    "q": "ข้อใดถูกต้องเกี่ยวกับ ciguatera fish poisoning",
    "options": [
      "เกิดจากการกินหอยแมลงภู่ที่ปนเปื้อน ciguatoxin มีอาการสูญเสียความจำและชัก",
      "เกิดจากการกินปลาปักเป้าที่มี ciguatoxin มีอาการชาที่ริมฝีปากและอัมพาตแบบลุกลามขึ้น",
      "เกิดจากการกินปลาที่ปนเปื้อน ciguatoxin มีอาการทางเดินอาหารและรับรู้ร้อนเย็นสลับกัน",
      "เกิดจากฮิสตามีนในปลาที่เก็บไม่เย็นพอ มีอาการหน้าแดง ผื่นคัน คล้ายแพ้อาหาร"
    ],
    "answer": 2,
    "explain": "Ciguatera fish poisoning เกิดจากการกินปลา (finfish) ที่ปนเปื้อน ciguatoxin ซึ่ง dinoflagellate สร้าง ทำให้มีทั้งอาการทางเดินอาหาร ได้แก่ ท้องเสีย ปวดท้อง คลื่นไส้ และอาเจียน และอาการทางประสาท เช่น รับรู้ร้อนเย็นสลับกัน ชาที่ริมฝีปาก ลิ้น และนิ้ว ปากแห้ง และตาพร่า มักระบาดในฮาวาย ฟลอริดา และเปอร์โตริโก ส่วนหอยที่ทำให้สูญเสียความจำและชักมี domoic acid ปลาปักเป้ามี tetrodotoxin และอาการหน้าแดงคล้ายแพ้อาหารเป็นของ scombroid fish poisoning",
