    "q": "สารพิษใดทำให้เกิด neurotoxic shellfish poisoning ซึ่งพบเมื่อน้ำทะเลเปลี่ยนเป็นสีแดงและมีปลาตายจำนวนมาก",
    "options": [
      "Brevetoxin",
      "Okadaic acid",
      "Domoic acid",
      "Azaspiracid"
    ],
    "answer": 0,
    "explain": "Neurotoxic shellfish poisoning (NSP) เกิดจากการกินหอยที่ปนเปื้อน brevetoxin ซึ่งสร้างโดย dinoflagellate ชื่อ Karenia brevis พบเมื่อน้ำทะเลเปลี่ยนเป็นสีแดงและมีปลาตายจำนวนมาก (Florida red tide) ระบาดหลักในสหรัฐอเมริกา (อ่าวเม็กซิโกและชายฝั่งแอตแลนติกตอนใต้) และนิวซีแลนด์ อาการทั้งทางเดินอาหารและทางประสาทเริ่มภายใน 30 นาทีถึงไม่กี่ชั่วโมงและหายภายใน 2 วัน ส่วน okadaic acid และ azaspiracid ทำให้เกิดอาการทางเดินอาหาร และ domoic acid ทำให้สูญเสียความจำ",
