    "answer": 1,
    "explain": "Puffer fish poisoning เกิดจากการกินปลาในอันดับ Tetraodontiformes เช่น ปลาปักเป้า (fugu) ที่มี tetrodotoxin ซึ่งสร้างโดยแบคทีเรีย อาการทางประสาทคล้าย PSP พบบ่อยในภูมิภาคแปซิฟิกใกล้ญี่ปุ่นและจีน และเสียชีวิตได้จากการกินปลาปักเป้าที่เตรียมไม่ถูกต้อง ส่วนอ่าวเม็กซิโกกับนิวซีแลนด์เป็นแหล่งระบาดของ NSP ฮาวาย ฟลอริดา และเปอร์โตริโกเป็นของ ciguatera และยุโรปกับแอฟริกาเหนือเป็นแหล่งของ AZP",
