    "q": "ข้อใดถูกต้องเกี่ยวกับ scombroid fish poisoning",
    "options": [
      "เกิดจากสารพิษที่ dinoflagellate สร้างและสะสมในหอยสองฝา อาการส่วนใหญ่รุนแรง",
      "เกิดจาก tetrodotoxin ในปลาทูน่า และมักเสียชีวิตจากระบบหายใจล้มเหลว",
      "เกิดจากฮิสตามีน แต่พบได้น้อยมาก และผู้ป่วยส่วนใหญ่มีอาการรุนแรงจนต้องใช้เครื่องช่วยหายใจ",
      "เกิดจากฮิสตามีน พบบ่อยที่สุดในโรคจากอาหารทะเล อาการคล้ายแพ้อาหาร ส่วนใหญ่หายเอง"
    ],
    "answer": 3,
    "explain": "Scombroid fish poisoning เกิดจากการกินปลาที่ปนเปื้อนฮิสตามีน เป็นโรคจากอาหารทะเลที่พบบ่อยที่สุดทั่วโลก รายงานบ่อยในญี่ปุ่น แคนาดา สหรัฐอเมริกา และสหราชอาณาจักร อาการคล้ายการแพ้อาหารแบบ IgE ได้แก่ หน้าแดง ผื่น คัน แสบร้อนในปาก คลื่นไส้ อาเจียน ท้องเสีย ปวดศีรษะ และเวียนศีรษะ รายที่รุนแรงอาจความดันต่ำ หัวใจเต้นเร็ว หายใจลำบาก และช็อก แต่ส่วนใหญ่ไม่รุนแรงและหายได้เอง ฮิสตามีนเกิดจากแบคทีเรียที่ทำให้เน่าเสีย ไม่ใช่จาก dinoflagellate",
