    "q": "ด้านเป็นประโยชน์ต่อสุขภาพ (beneficial to health) ของอนามัยเนื้อสัตว์ (wholesomeness of meat) พิจารณาจากข้อใด",
    "options": [
      "อันตรายทางชีวภาพ เคมี และกายภาพที่อาจปนเปื้อนมากับเนื้อจนไม่ปลอดภัยต่อการบริโภค",
      "การตรวจเนื้อโดยหน่วยงานรัฐ และการประทับตรารับรองบนชิ้นเนื้อขนาดใหญ่",
      "ลักษณะที่พึงประสงค์ของเนื้อ เช่น สี ความนุ่ม และรสชาติที่ผู้บริโภคต้องการ",
      "คุณค่าทางโภชนาการ เช่น อัตราส่วน P:S อัตราส่วน n-6:n-3 และกรดไขมันจำเป็น"
    ],
    "answer": 3,
    "explain": "อนามัยเนื้อสัตว์มีสองด้าน ด้านแรกคือปลอดภัยต่อการบริโภค พิจารณาอันตรายทางชีวภาพ เคมี และกายภาพ ด้านที่สองคือเป็นประโยชน์ต่อสุขภาพ พิจารณาคุณค่าทางโภชนาการ เช่น อัตราส่วนกรดไขมันไม่อิ่มตัวหลายตำแหน่งต่อกรดไขมันอิ่มตัว (P:S ratio) อัตราส่วน n-6:n-3 และกรดไขมันจำเป็น การตรวจโดยรัฐและการประทับตราเป็นกลไกรับรองอนามัยของเนื้อ ส่วนสี ความนุ่ม และรสชาติเป็น functional quality ไม่ใช่เกณฑ์ด้านประโยชน์ต่อสุขภาพ",
