    "q": "การทำสลบแบบอ่างน้ำ (water bath stunning) จัดอยู่ในการทำสลบกลุ่มใด และใช้กับสัตว์ชนิดใด",
    "options": [
      "การทำสลบด้วยก๊าซ ใช้กับสุกรโดยให้สูด CO2 ความเข้มข้นมากกว่า 80% โดยปริมาตร (ดีที่สุด 90%)",
      "การทำสลบแบบกล ใช้กับโคที่อยู่ในซองบังคับ โดยยิง captive bolt เข้ากลางหน้าผากของสัตว์",
      "การทำสลบด้วยไฟฟ้าแบบ head-only ใช้กับสุกร โดยปล่อยกระแสผ่านสมองอย่างเดียวด้วย stunning wand",
      "การทำสลบด้วยไฟฟ้า ใช้กับสัตว์ปีกที่แขวนบน shackle แล้วจุ่มหัวและคอในอ่างน้ำที่มีไฟฟ้า"
    ],
    "answer": 3,
    "explain": "Water bath stunning เป็นการทำสลบด้วยไฟฟ้าอีกแบบหนึ่งนอกจาก direct electrical stunning ใช้กับสัตว์ปีกที่แขวนบน shackle แล้วจุ่มหัวและคอลงในอ่างน้ำที่มีกระแสไฟฟ้า กระแสผ่านทั้งตัว มีทั้งแบบที่สัตว์ฟื้นได้ (reversible) ใช้แรงดันต่ำความถี่สูง และแบบไม่ฟื้น (non-reversible) ใช้แรงดันสูงความถี่สูงกว่า การทำสลบด้วยก๊าซ CO2 และการยิง captive bolt เป็นอีกสองกลุ่มของวิธีทำสลบ",
