    "q": "Yield grade ของซากโคประเมินจากอะไร",
    "options": [
      "ความแก่ของซาก (maturity) และปริมาณไขมันแทรก (marbling) ที่หน้าตัดกล้ามเนื้อ ribeye",
      "ความหนาของไขมันสันหลังที่ซี่โครงสุดท้าย และระดับกล้ามเนื้อ (degree of muscling) ของซาก",
      "ร้อยละของชิ้นเนื้อขายปลีกไม่มีกระดูกที่ตัดแต่งแล้ว (%CTBRC) จาก chuck, rib, loin และ round",
      "รูปร่าง ความเต็มของเนื้อและไขมันคลุม การถอนขน และตำหนิที่มองเห็นบนซาก"
    ],
    "answer": 2,
    "explain": "Yield grade ใช้ร้อยละของชิ้นเนื้อขายปลีกไม่มีกระดูกที่ตัดแต่งชิดแล้ว (combined yield of closely trimmed, boneless retail cuts หรือ %CTBRC) จากชิ้นส่วนหลัก (major primal cuts) สี่ชิ้น คือ chuck, rib, loin และ round แบ่งเป็น 5 ระดับ yield grade 1 มี %CTBRC มากกว่า 52.3 ส่วน yield grade 5 น้อยกว่า 45.4 ความหนาของไขมันสันหลังที่ซี่โครงสุดท้ายและระดับกล้ามเนื้อใช้คาดผลผลิตของ 4 lean cuts ในการจัดเกรดซากสุกร ส่วนรูปร่าง ความเต็มของเนื้อ ไขมันคลุม การถอนขน และตำหนิของซาก เป็นปัจจัยการจัดเกรดคุณภาพสัตว์ปีก",
