    "model_answer": "(1) ผลจะช้า โดยเฉพาะยาที่ออกฤทธิ์เรื้อรังหรือห้ามการแข็งตัวของเลือด (2) หลังใช้ไปช่วงหนึ่ง หนูอาจไม่กินหรือเลี่ยงเหยื่อ (3) อันตรายต่อสัตว์เลี้ยง และอาจรวมถึงคน จะมากขึ้นเมื่อเหยื่อน่ากินมากขึ้น (4) หนูที่กินเหยื่ออาจไม่ตายในที่โล่ง ทำให้เกิดปัญหากลิ่น (5) เหยื่ออาจราคาค่อนข้างสูง โดยเฉพาะเมื่อต้องล่อก่อนด้วยเหยื่อที่ไม่มียา (prebaiting) (6) ต้องระวังการจับต้องและการเก็บ เพราะยาฆ่าหนูเป็นสารพิษร้ายแรงถึงตาย",
