    "explain": "Pasteurization ของผลิตภัณฑ์เนื้อให้ความร้อนแก่ผลิตภัณฑ์ที่ 65 ถึง 77 °C (150 ถึง 170 °F) โดยอุณหภูมิแกนกลางของผลิตภัณฑ์อยู่ที่ 58 ถึง 75 °C ความร้อนระดับนี้ฆ่าจุลินทรีย์ได้ส่วนใหญ่แต่ไม่ทั้งหมด ผลิตภัณฑ์จึงต้องเก็บในตู้เย็น ช่วง 65 ถึง 77 °C เป็นอุณหภูมิที่ใช้ให้ความร้อนแก่ผลิตภัณฑ์ ไม่ใช่อุณหภูมิที่แกนกลาง ส่วนการฆ่าจุลินทรีย์ได้ทั้งหมดรวมทั้งสปอร์เป็นผลของ sterilization ซึ่งให้ความร้อนสูงกว่า 100 °C (250 °F) ภายใต้ความดัน ผลิตภัณฑ์จึงเก็บได้โดยไม่ต้องแช่เย็น",
