      "Lactobacillus และ Brochothrix thermosphacta ซึ่งเจริญได้ในสภาพที่ไม่มีออกซิเจน",
      "Shewanella putrefaciens และ Serratia liquefaciens ซึ่งเป็นแกรมลบ facultative anaerobe",
