    "q": "เนื้อ DFD ที่บรรจุแบบสุญญากาศเน่าเสียโดยมีสีเขียวและกลิ่นผิดปกติ จุลินทรีย์ชนิดใดเป็นสาเหตุหลักของสีเขียว ชนิดใดเป็นสาเหตุหลักของกลิ่น และป้องกันแต่ละปัญหาได้ด้วยการเติมสารใด",
