    "model_answer": "สีเขียวเกิดจาก Shewanella putrefaciens (เดิมเรียก Alteromonas putrefaciens) เป็นหลัก เพราะ H2S ที่เชื้อสร้างทำปฏิกิริยากับ myoglobin ป้องกันได้ด้วยการเติม citrate buffer ส่วนกลิ่นเน่าเกิดจาก Serratia liquefaciens (เดิมเรียก Enterobacter liquefaciens) เป็นหลัก ป้องกันได้ด้วยการเติม glucose หรือ citrate",
    "explain": "เนื้อ DFD มี pH มากกว่า 6.0 และมีกลูโคสน้อยหรือไม่มีเลย จึงเน่าเสียเร็วกว่าเนื้อที่มี pH ปกติ เมื่อบรรจุสุญญากาศจะเกิดกลิ่นผิดปกติและสีเขียวที่เป็นลักษณะเฉพาะ จุลินทรีย์หลักคือ Shewanella putrefaciens และ Serratia liquefaciens โดย S. putrefaciens สร้าง H2S ในสภาพไม่มีออกซิเจน แล้ว H2S ทำปฏิกิริยากับ myoglobin จนเนื้อเป็นสีเขียว การเติม citrate buffer ช่วยป้องกันสีเขียว ส่วนกลิ่นเน่ามาจาก S. liquefaciens เป็นหลัก และป้องกันได้ด้วยการเติม glucose หรือ citrate ทั้งสองปัญหาจึงมีเชื้อต้นเหตุและสารป้องกันของตัวเอง S. liquefaciens ยังเจริญบนเนื้อ pH ปกติได้ แต่ช้ากว่าบนเนื้อ DFD",
