    "q": "ตามเกณฑ์เนื้อสัตว์ที่ไม่เหมาะสมที่จะใช้เป็นอาหาร ข้อ 4 ว่าด้วยสัตว์ที่มีหรือสงสัยว่ามีสารตกค้าง จงยกตัวอย่างสารตกค้างที่ข้อนี้ระบุชื่อไว้ 5 ชนิด",
