    "model_answer": "สารที่ข้อ 4 ระบุชื่อไว้มี 9 รายการ ได้แก่ กลุ่มเบต้าอะโกนิสต์ (beta-agonist) กลุ่มไนโตรฟูแรนส์ (nitrofurans) กลุ่มไนโตรอิมิดาโซล (nitroimidazoles) คลอแรมเฟนิคอล (chloramphenicol) อะโวพาร์ซิน (avoparcin) คาร์บาดอกซ์ (carbadox) โอลาควินดอกซ์ (olaquindox) ไดเอทิลสติลเบสโทรล (diethylstilbestrol, DES) และเมลามีนหรือสารในกลุ่มเมลามีน (melamine)",
    "explain": "ข้อ 4 ให้ถือว่าเนื้อจากสัตว์ที่มีหรือสงสัยว่ามีสารตกค้างในรายการไม่เหมาะสมที่จะใช้เป็นอาหาร สารที่ระบุชื่อคือ 9 รายการแรก ส่วนรายการที่ 10 ถึง 12 อ้างกฎหมายอื่น ได้แก่ สารพิษตกค้างที่เกินปริมาณสูงสุดตามกฎหมายว่าด้วยมาตรฐานสินค้าเกษตร ยาสัตว์ตกค้างเกินปริมาณที่กำหนดตามกฎหมายว่าด้วยอาหาร และวัตถุที่ห้ามใช้เป็นส่วนผสมในอาหารสัตว์ตามกฎหมายว่าด้วยการควบคุมคุณภาพอาหารสัตว์ ข้อ 4 จึงต่างจากข้อ 1 ที่ว่าด้วยสัตว์ที่เป็นโรค ข้อ 2 ที่ว่าด้วยลักษณะของสัตว์ และข้อ 3 ที่ว่าด้วยลักษณะของเนื้อสัตว์",
